{{-- CSS của trang chủ — SAO NGUYÊN VĂN từ docs/hoctoan-layout-v6/index.html (yêu cầu giống 100%).  --}}
@verbatim
<style>
:root{--ink:#182448;--muted:#62708d;--primary:#5743e5;--blue:#2875d8;--border:#e2e7f3;--bg:#f6f8fe;--mint:#e9f8f2;--green:#157c61;--shadow:0 18px 60px rgba(31,43,91,.09)}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;color:var(--ink);background:white;font:15px/1.65 system-ui,-apple-system,'Segoe UI',sans-serif}a{color:inherit;text-decoration:none}button,select{font:inherit}button{cursor:pointer}button:focus-visible,a:focus-visible,select:focus-visible{outline:3px solid #ffbf47;outline-offset:3px}.container{max-width:1160px;margin:auto;padding:0 22px}.top{background:#edeaff;color:#4c40a7;text-align:center;padding:8px 14px;font-size:12px;font-weight:700}.nav{height:76px;display:flex;align-items:center;justify-content:space-between;gap:18px}.brand{font-size:19px;font-weight:850;letter-spacing:-.6px;display:flex;align-items:center;gap:10px}.mark{width:41px;height:41px;border-radius:13px;background:linear-gradient(140deg,var(--primary),#2781e6);color:white;display:grid;place-items:center;font-size:23px}.navlinks{display:flex;gap:22px;font-size:13px;font-weight:700}.navlinks a:hover,.foot a:hover{color:var(--primary)}.navright{display:flex;align-items:center;gap:12px}.navright .login{font-size:13px;font-weight:700}.btn{display:inline-flex;align-items:center;justify-content:center;gap:9px;border:1px solid transparent;background:var(--primary);color:white;border-radius:13px;padding:13px 20px;font-weight:750;line-height:1.3;transition:transform .18s,background .18s}.btn:hover{background:#4531d1;transform:translateY(-1px)}.btn.secondary{background:white;color:var(--primary);border-color:#cbc7fa}.btn.secondary:hover{background:#f2efff}.menu-btn{display:none;border:0;background:none;font-size:26px}.mobile-menu{display:none}.hero{padding:66px 0 75px;background:radial-gradient(circle at 87% 15%,#ece7ff 0,transparent 35%),linear-gradient(130deg,#f8faff,#fff 60%,#f4f1ff)}.hero-grid{display:grid;grid-template-columns:1fr 1fr;align-items:center;gap:48px}.eyebrow,.tag{display:inline-block;font-size:12px;font-weight:800;color:#5a45d7;letter-spacing:.4px}.eyebrow{background:#eeeaff;border:1px solid #ddd5ff;border-radius:40px;padding:8px 13px}.hero h1{font-size:clamp(33px,4.25vw,54px);line-height:1.19;letter-spacing:-1.6px;margin:20px 0}.accent{color:var(--primary)}.lead{color:#55627e;font-size:16px;max-width:570px}.benefits{display:flex;gap:13px 20px;flex-wrap:wrap;margin:23px 0}.benefits span{font-size:12px;font-weight:700}.benefits b{color:var(--green)}.entry{background:white;border:1px solid var(--border);padding:19px;border-radius:20px;box-shadow:var(--shadow);margin-top:24px}.entry label{font-size:12px;font-weight:750;display:block;margin-bottom:7px}.fields{display:flex;gap:11px;align-items:end}.field{flex:1;min-width:0}.entry select{width:100%;height:47px;padding:0 10px;border:1px solid #d9deeb;border-radius:11px;background:white;color:var(--ink)}.entry .btn{min-height:47px;white-space:nowrap}.micro{font-size:12px;color:#6d7890;margin:12px 0 0}.hero-art{position:relative}.hero-art img{width:100%;display:block;border-radius:32px;box-shadow:0 25px 60px #29385a20}.float{position:absolute;background:#fff;border:1px solid #eceafa;border-radius:16px;box-shadow:var(--shadow);padding:13px 17px;font-size:12px;max-width:195px}.float strong{display:block;font-size:13px}.float small{color:var(--muted)}.float.one{top:8%;left:-30px}.float.two{bottom:8%;right:-18px}.section{padding:82px 0}.soft{background:var(--bg)}.head{max-width:720px;margin:0 auto 36px;text-align:center}.head h2,.section h2{font-size:clamp(26px,3vw,37px);line-height:1.3;letter-spacing:-.9px;margin:10px 0 13px}.head p,.copy{color:var(--muted)}.grid{display:grid;gap:18px}.three{grid-template-columns:repeat(3,1fr)}.four{grid-template-columns:repeat(4,1fr)}.card{border:1px solid var(--border);border-radius:22px;background:white;padding:25px;box-shadow:0 10px 30px #1b2b5809}.card h3{font-size:17px;line-height:1.4;margin:9px 0}.card p{font-size:13px;color:var(--muted);margin:0}.card .emoji{font-size:29px}.split{display:grid;grid-template-columns:1fr 1fr;gap:60px;align-items:center}.quiz{border:1px solid #e0def8;border-radius:23px;background:white;box-shadow:var(--shadow);overflow:hidden}.quiz-top{background:#f2efff;padding:18px 23px;display:flex;justify-content:space-between;align-items:center;font-size:13px;font-weight:750}.quiz-body{padding:26px}.quiz-question{font-size:23px;font-weight:800;line-height:1.4;margin:14px 0 19px}.choices{display:grid;grid-template-columns:1fr 1fr;gap:10px}.choice{border:1px solid #dce1ef;border-radius:12px;padding:14px;text-align:left;background:white;font-weight:750;color:var(--ink)}.choice:hover,.choice:focus-visible{border-color:var(--primary);background:#f4f1ff}.choice.selected{border:2px solid var(--primary);background:#f2efff}.choice.correct{border-color:#159e77;background:#e9f8f2}.feedback{min-height:55px;font-size:13px;margin:15px 0 0;color:#46536d}.result{background:#f5f7ff;border-radius:14px;padding:17px;margin:15px 0}.result strong{font-size:23px}.bullet{padding:0;list-style:none}.bullet li{margin:13px 0;display:flex;gap:11px}.bullet li:before{content:'✓';color:var(--green);font-weight:900}.mini-note{font-size:12px;color:#74809a}.process{counter-reset:s}.step:before{counter-increment:s;content:counter(s);width:36px;height:36px;border-radius:50%;display:grid;place-items:center;background:#eeeaff;color:var(--primary);font-weight:850}.tutor{border:1px solid #e1ddff;background:#f6f4ff;border-radius:23px;padding:24px}.bubble{border-radius:15px;padding:13px 16px;font-size:14px;max-width:90%;margin:12px 0}.bubble.ai{background:white;border:1px solid #e4e1f4}.bubble.student{background:var(--primary);color:white;margin-left:auto}.dash{border:1px solid var(--border);border-radius:23px;box-shadow:var(--shadow);background:white;overflow:hidden}.dash-head{background:#1c2c51;color:white;padding:14px 20px;font-size:12px}.dash-inner{padding:23px}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.stat{background:#f8faff;border:1px solid #e7eaf4;padding:13px;border-radius:13px}.stat strong{display:block;font-size:24px}.stat small{color:var(--muted);font-size:11px}.bars{height:155px;display:flex;align-items:end;gap:16px;padding:15px 10px 25px;border-bottom:1px solid #dbe1ef;margin:16px 0 30px;background:repeating-linear-gradient(to top,#edf0f7 0,#edf0f7 1px,transparent 1px,transparent 35px)}.bar{flex:1;background:linear-gradient(#8b7afc,#c8bfff);border-radius:7px 7px 0 0;position:relative}.bar span{position:absolute;bottom:-24px;left:50%;transform:translateX(-50%);font-size:10px;white-space:nowrap;color:var(--muted)}.notice{background:var(--mint);color:#25694e;padding:13px;border-radius:12px;font-size:12px}.pricing{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.plan{display:flex;flex-direction:column}.plan.featured{border:2px solid var(--primary);box-shadow:0 17px 43px #5743e520}.plan .amount{font-size:25px;font-weight:850;margin:12px 0}.plan ul{padding-left:20px;flex:1;color:#52617e;font-size:13px;line-height:2}.plan .btn{width:100%;margin-top:16px}.ribbon{color:var(--primary);font-size:12px;font-weight:800}.trust-box{background:white;border:1px solid var(--border);border-radius:20px;padding:25px}.trust-box h3{margin:0 0 9px}.trust-box p{font-size:13px;color:var(--muted)}.faq{max-width:830px;margin:auto}.faq details{padding:19px 4px;border-bottom:1px solid var(--border)}.faq summary{cursor:pointer;font-weight:750}.faq p{font-size:14px;color:var(--muted)}.cta{background:linear-gradient(110deg,#513bd6,#2977db);border-radius:28px;color:white;padding:45px;display:flex;justify-content:space-between;align-items:center;gap:25px}.cta h2{margin:0 0 9px}.cta p{margin:0;color:#e7e7ff}.cta .btn{background:white;color:#4939c8;white-space:nowrap}.foot{background:#182748;color:#cbd4e7;padding:54px 0 25px}.foot-grid{display:grid;grid-template-columns:2fr 1fr 1fr;gap:30px}.foot h3{color:white}.foot a{display:block;font-size:13px;margin:10px 0}.foot p{font-size:13px}.bottom{border-top:1px solid #ffffff25;margin-top:32px;padding-top:20px;font-size:12px}.sticky{display:none}.hide{display:none!important}
@media(max-width:1080px){.navlinks{gap:13px}.hero-grid{gap:26px}.float.one{left:-5px}.fields{flex-wrap:wrap}.entry .btn{width:100%}}@media(max-width:800px){.navlinks,.navright{display:none}.menu-btn{display:block}.mobile-menu.open{display:flex;flex-direction:column;gap:12px;padding:16px 22px;border-top:1px solid var(--border);background:white}.hero-grid,.split{grid-template-columns:1fr}.hero{padding:39px 0 62px}.hero-art{max-width:650px;margin:auto}.three,.four,.pricing{grid-template-columns:1fr 1fr}.section{padding:58px 0}.foot-grid{grid-template-columns:1fr 1fr}.sticky{display:block;position:fixed;bottom:0;left:0;right:0;background:#fffffff2;border-top:1px solid var(--border);padding:10px 16px;z-index:10;backdrop-filter:blur(10px)}.sticky .btn{width:100%}.foot{padding-bottom:95px}}@media(max-width:580px){.container{padding:0 17px}.brand{font-size:16px}.hero h1{font-size:35px}.float{font-size:10px;padding:9px}.float strong{font-size:11px}.three,.four,.pricing,.foot-grid{grid-template-columns:1fr}.fields{display:block}.field{margin-bottom:12px}.hero-art img{border-radius:24px}.stats{gap:5px}.stat{padding:8px}.stat strong{font-size:19px}.choices{grid-template-columns:1fr}.cta{padding:28px;display:block}.cta .btn{margin-top:22px}.quiz-body{padding:18px}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}.btn{transition:none}}

/* V4: lộ trình học cá nhân hóa */
.path-panel{border:1px solid #deddf6;border-radius:25px;background:white;box-shadow:var(--shadow);overflow:hidden}.path-head{background:linear-gradient(110deg,#f2efff,#f6f9ff);padding:24px;display:flex;align-items:center;justify-content:space-between;gap:10px}.path-head h3{font-size:20px;margin:5px 0 0;line-height:1.3}.path-kicker{font-size:10px;font-weight:850;letter-spacing:1.2px;color:var(--primary)}.path-pill{font-size:11px;color:#5944c9;background:white;border:1px solid #e1dafa;border-radius:30px;padding:7px 11px;white-space:nowrap}.path-content{padding:25px}.path-content label{display:block;font-size:13px;font-weight:750;margin-bottom:8px}.path-content select{display:block;width:100%;padding:13px 15px;background:white;border:1px solid #d8def0;border-radius:12px;color:var(--ink);font:inherit}.path-intro{display:flex;gap:13px;align-items:center;background:#f6f8ff;border-radius:15px;padding:15px;margin:20px 0}.path-avatar{width:42px;height:42px;display:grid;place-items:center;border-radius:12px;background:white;font-size:23px}.path-intro strong,.path-intro small{display:block}.path-intro strong{font-size:14px}.path-intro small{font-size:11px;color:var(--muted);margin-top:4px}.path-timeline{margin-left:17px}.path-step{position:relative;display:flex;gap:15px;padding:0 0 23px}.path-step:not(:last-child):before{content:'';position:absolute;left:18px;top:37px;bottom:0;border-left:2px dashed #d8d3f8}.path-num{flex:0 0 38px;height:38px;display:grid;place-items:center;border-radius:12px;background:#efecff;color:var(--primary);font-weight:850;font-size:12px}.path-step strong{font-size:14px}.path-step p{margin:4px 0 0;color:var(--muted);font-size:12px;line-height:1.6}.path-action{width:100%}.path-disclaimer{text-align:center;margin-bottom:0}.path-panel select:focus-visible{outline:3px solid #ffbf47;outline-offset:3px}#entryForm{scroll-margin-top:20px}@media(max-width:580px){.path-head{padding:18px}.path-content{padding:18px}.path-pill{font-size:10px}.path-timeline{margin-left:0}}
.problems-section{padding-top:66px;padding-bottom:66px}.problem-card{position:relative;display:flex;flex-direction:column;gap:7px;box-shadow:none}.problem-icon{font-size:30px;background:#f1efff;width:54px;height:54px;border-radius:16px;display:grid;place-items:center}.problem-tip{font-size:12px;color:#5143aa;background:#f5f3ff;border-radius:10px;padding:10px 12px;margin-top:auto}.dash-topics{display:grid;gap:9px;margin:0 0 15px}.dash-topics>div{display:flex;justify-content:space-between;gap:12px;border-bottom:1px solid #edf0f8;padding:7px 0;font-size:12px}.dash-topics span{color:var(--muted)}.dash-topics strong{text-align:right}.trust-section .trust-box{box-shadow:none}.section{scroll-margin-top:18px}@media(max-width:580px){.dash-topics>div{flex-direction:column;gap:2px}.dash-topics strong{text-align:left}.problems-section{padding-top:48px;padding-bottom:48px}} 
/* V6: ưu tiên nội dung rõ ràng và ít trùng lặp */
.pricing{grid-template-columns:repeat(2,minmax(0,1fr));max-width:880px;margin:auto}.coming-plan{background:#f9faff}.plan-info{background:#fff;border:1px solid var(--border);border-radius:14px;padding:16px;margin-top:18px;font-size:13px}.plan-info ul{margin:8px 0 0}.dash-topics{background:#f8faff;border:1px solid var(--border);border-radius:14px;padding:10px 15px;margin:14px 0 20px}.dash-topics>div:last-child{border-bottom:0}.dash .bars{height:120px;margin-top:8px}.path-step:last-child{padding-bottom:0}@media(max-width:580px){.pricing{grid-template-columns:1fr}}

/* --- Phần ngoài mẫu V6: dải cookie (bắt buộc theo luật, markup ở components/cookie-consent) --- */
.cookie-consent{position:fixed;left:0;right:0;bottom:0;z-index:2100;display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:.75rem 1.25rem;padding:.875rem 1rem calc(.875rem + env(safe-area-inset-bottom,0px));background:#182448;color:rgba(255,255,255,.85);font-size:13px;line-height:1.5;box-shadow:0 -6px 24px rgba(15,23,42,.3)}.cookie-consent a{color:#fff;text-decoration:underline}.cookie-consent__text{flex:1 1 320px}.cookie-consent__actions{display:flex;flex-wrap:wrap;gap:8px}.cookie-consent__actions form{margin:0}.cookie-consent .btn{padding:8px 14px;font-size:13px;border-radius:10px}.cookie-consent .btn-outline-light{background:transparent;border-color:rgba(255,255,255,.5)}.cookie-consent .btn-outline-light:hover{background:rgba(255,255,255,.12)}
/* Logo chính (public/images/logo.webp) thay ô ∑ của mẫu V6; ảnh nền trắng nên trên footer tối đặt trong ô trắng. */
.site-logo{display:block;height:52px;width:auto;max-width:100%}.site-logo-plate{display:inline-flex;padding:8px 12px;background:#fff;border-radius:12px}@media(max-width:560px){.site-logo{height:42px}}
/* Sửa tràn ngang trên điện thoại (mẫu V6 bị): ô grid mặc định không co nhỏ hơn nội dung, nút nowrap giữ cột rộng 344px → màn dưới 378px tràn; .float.two thò 18px quá lề 17px. Đừng che bằng overflow:hidden — sẽ cắt mất chữ. */
.hero-grid>*{min-width:0}@media(max-width:580px){.entry .btn{white-space:normal}.float.two{right:-10px}}
</style>
@endverbatim
